    printk(KERN_DEBUG "Processing class name: %s, attribute name: %s\n", class_name, attr_name);

    attr_value = find_attribute_value_by_class(class_name, attr_name);
    if (!attr_value) {
        printk(KERN_ERR "Attribute not found for the specified class.\n");
        error = -ENOENT;
    }

    if (error) {
        send_error_response(skb, error);
    } else {
        send_successful_response(skb, attr_value, sizeof(*attr_value));
    }
}

void iriap_handle_get_by_class(struct iriap_cb *self, struct sk_buff *skb)
{
    struct iriap_get_by_class_req *req;
    struct iriap_get_by_class_rsp *rsp;
    struct iriap_object *obj;
    struct iriap_attribute *attr;
    int err;

    if (!self || !skb) {
        net_dbg("Invalid parameters in iriap_handle_get_by_class\n");
        return;
    }

    req = (struct iriap_get_by_class_req *)skb->data;
    net_dbg("Received class-based get request: class='%s', attribute='%s'\n",
            req->class_name, req->attr_name);

    obj = iriap_find_object_by_class(req->class_name);
    if (!obj) {
        net_dbg("Class '%s' not found in iriap_handle_get_by_class\n", req->class_name);
        iriap_send_error(skb, IRIAP_ERR_OBJ_NOT_FOUND);
        return;
    }

    attr = iriap_find_attribute(obj, req->attr_name);
    if (!attr) {
        net_dbg("Attribute '%s' not found for class '%s'\n",
                req->attr_name, obj->name);
        iriap_send_error(skb, IRIAP_ERR_ATTR_NOT_FOUND);
        return;
    }

    net_dbg("Found attribute '%s' in class '%s', retrieving value\n",
            attr->name, obj->name);

    rsp = iriap_build_get_by_class_rsp(skb, obj, attr);
    if (!rsp) {
        net_dbg("Failed to build response for get by class\n");
        iriap_send_error(skb, IRIAP_ERR_INTERNAL);
        return;
    }

    iriap_send_response(skb, rsp);
    net_dbg("Attribute value sent successfully for '%s' in class '%s'\n",
            attr->name, obj->name);
}

void iriap_handle_get_attr_by_class(struct iriap_cb *self, struct sk_buff *skb)
{
    struct iriap_class_attr *class_attr;
    struct sk_buff *resp_skb;
    char *class_name, *attr_name;
    int class_len, attr_len;
    int ret;

    if (!self || !skb)
        return;

    class_name = skb->data;
    class_len = strlen(class_name);
    attr_name = class_name + class_len + 1;
    attr_len = strlen(attr_name);

    class_attr = find_class_attr(self, class_name, attr_name);
    if (!class_attr) {
        resp_skb = alloc_skb(128, GFP_KERNEL);
        if (!resp_skb)
            return;

        ret = iriap_build_error_response(resp_skb, IRIAP_ERR_NO_SUCH_OBJECT);
        if (ret < 0)
            kfree_skb(resp_skb);
        else
            iriap_send_response(self, resp_skb);
        return;
    }

    resp_skb = alloc_skb(128, GFP_KERNEL);
    if (!resp_skb)
        return;

    ret = iriap_build_success_response(resp_skb, class_attr->value, strlen(class_attr->value));
    if (ret < 0)
        kfree_skb(resp_skb);
    else
        iriap_send_response(self, resp_skb);
}

void iriap_get_attribute_by_class(struct iriap_cb *self, struct sk_buff *skb)
{
    struct iriap_object *object;
    struct iriap_attribute *attribute;
    char *class_name, *attribute_name;
    int class_len, attr_len;

    if (!self || !skb) {
        pr_debug("Invalid input parameters\n");
        return;
    }

    /* Extract and process class name and attribute name from skb */
    class_name = skb->data;
    class_len = strnlen(class_name, skb->len);
    if (class_len == 0 || class_len >= skb->len) {
        pr_debug("Invalid class name in skb\n");
        return;
    }

    attribute_name = class_name + class_len + 1;
    attr_len = strnlen(attribute_name, skb->len - (attribute_name - skb->data));
    if (attr_len == 0) {
        pr_debug("Invalid attribute name in skb\n");
        return;
    }

    pr_debug("Looking up class: %s, attribute: %s\n", class_name, attribute_name);

    object = iriap_find_object_by_name(self, class_name);
    if (!object) {
        pr_debug("Object not found: %s\n", class_name);
        iriap_send_error_response(skb, IRIAP_ERR_OBJECT_NOT_FOUND);
        return;
    }

    attribute = iriap_find_attribute_by_name(object, attribute_name);
    if (!attribute) {
        pr_debug("Attribute not found: %s in object %s\n", attribute_name, class_name);
        iriap_send_error_response(skb, IRIAP_ERR_ATTRIBUTE_NOT_FOUND);
        return;
    }

    pr_debug("Retrieving attribute value for %s.%s\n", class_name, attribute_name);
    iriap_send_attribute_value(skb, attribute->value, attribute->value_len);
}
